import { brand } from './brand';
import { invoke } from '@tauri-apps/api/core';
import { pipelineRequest, request } from './api';

/** The local model prepared and verified automatically by the desktop host. */
export const TRANSCRIPTION_MODEL = 'Qwen3-ASR-1.7B';
/** Minutes are generated by the organisation's document worker through its configured gateway (docs/synth/architecture.md). */
export const SYNTH_DOCUMENT_ROUTE = 'configured_gateway';

export type CheckState = 'pending' | 'ok' | 'warn' | 'error';
export type CheckKey = 'model' | 'service' | 'synth' | 'minutes';
export interface Check { key: CheckKey; label: string; state: CheckState; value: string; fix?: string }
export type Permission = 'mic' | 'system';
export type PermissionState = 'unknown' | 'granted' | 'denied';

interface HostStatus { worker?: Record<string, unknown>; document_route?: string; asr_backend?: string; audio_setup?: { state: string; message?: string } }

export const CHECK_LABELS: Record<CheckKey, string> = {
  model: 'Modelo de transcripción', service: 'Servicio de este Mac', synth: `Conexión con ${brand.name}`, minutes: 'Actas',
};

export function pendingChecks(): Check[] {
  return (Object.keys(CHECK_LABELS) as CheckKey[]).map(key => ({ key, label: CHECK_LABELS[key], state: 'pending', value: 'Comprobando…' }));
}

async function checkHost(): Promise<[Check, Check, Check]> {
  try {
    const status = await pipelineRequest<HostStatus>('GET', '/v1/status');
    const synthRoute = status.document_route === SYNTH_DOCUMENT_ROUTE;
    const ready = status.audio_setup?.state === 'ready' && status.asr_backend === 'qwen3';
    const preparing = ['checking', 'preparing'].includes(status.audio_setup?.state ?? '');
    return [
      { key: 'model', label: CHECK_LABELS.model, state: ready ? 'ok' : preparing ? 'pending' : 'error',
        value: ready ? TRANSCRIPTION_MODEL : preparing ? 'Preparando Qwen…' : 'Qwen pendiente',
        ...(!ready && !preparing ? { fix: status.audio_setup?.message ?? 'Reintenta la preparación automática del audio.' } : {}) },
      { key: 'service', label: CHECK_LABELS.service, state: 'ok', value: 'En marcha' },
      synthRoute
        ? { key: 'minutes', label: CHECK_LABELS.minutes, state: 'ok', value: 'Servicio de actas de tu organización' }
        : { key: 'minutes', label: CHECK_LABELS.minutes, state: 'warn', value: 'Entorno de desarrollo', fix: 'Esta instalación no apunta al servicio de tu organización.' },
    ];
  } catch {
    const fix = `Cierra y vuelve a abrir ${brand.name}.`;
    return [
      { key: 'model', label: CHECK_LABELS.model, state: 'error', value: 'Sin comprobar', fix },
      { key: 'service', label: CHECK_LABELS.service, state: 'error', value: 'No responde', fix },
      { key: 'minutes', label: CHECK_LABELS.minutes, state: 'error', value: 'Sin comprobar', fix },
    ];
  }
}

async function checkSynth(): Promise<Check> {
  try {
    const me = await request<{ name: string }>('GET', '/v1/me');
    return { key: 'synth', label: CHECK_LABELS.synth, state: 'ok', value: me.name };
  } catch {
    return { key: 'synth', label: CHECK_LABELS.synth, state: 'error', value: 'Sin conexión', fix: 'Comprueba tu conexión a internet y vuelve a comprobar.' };
  }
}

export async function runChecks(): Promise<Check[]> {
  const [[model, service, minutes], synth] = await Promise.all([checkHost(), checkSynth()]);
  return [model, service, synth, minutes];
}

/** Recording needs the model, the local service and the account; the minutes route only warns. */
export function readyToRecord(checks: Check[]): boolean {
  return checks.every(check => check.state === 'ok' || check.state === 'warn');
}

export async function requestPermission(kind: Permission): Promise<PermissionState> {
  try {
    const granted = await invoke<boolean>(kind === 'mic' ? 'trigger_microphone_permission' : 'trigger_system_audio_permission_command');
    return granted ? 'granted' : 'denied';
  } catch {
    return 'denied';
  }
}

export function openPrivacySettings(): Promise<void> {
  return invoke('open_system_settings');
}

export async function setupCompleted(): Promise<boolean> {
  const status = await invoke<{ completed: boolean } | null>('get_onboarding_status');
  return status?.completed ?? false;
}

/** Marks the first run as done and configures transcription; the tray only offers recording afterwards. */
export function completeSetup(): Promise<void> {
  return invoke('complete_onboarding', { model: 'instant-combo' });
}

export function restartSetup(): Promise<void> {
  return invoke('reset_onboarding_status_cmd');
}
